"""Generates the shared test fixtures in this folder (issue #10).

The phone (Kotlin) and the PC (C++) are both tested against these files, so a change to the
protocol bytes on one side fails the other side's tests. This script is a third, independent
implementation of the formats in docs/protocol.md, using Python's `cryptography` package:

    python -m pip install cryptography
    python tests/fixtures/gen_fixtures.py

The inputs are fixed, so the output only changes when this script changes. Regenerate and commit
both .txt files together with any intended protocol change.
"""

import hashlib
import hmac
from pathlib import Path

from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.serialization import Encoding, PublicFormat

HERE = Path(__file__).resolve().parent
P256_ORDER = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551


def sha256(*parts: bytes) -> bytes:
    return hashlib.sha256(b"".join(parts)).digest()


def private_key(seed: str) -> ec.EllipticCurvePrivateKey:
    scalar = int.from_bytes(sha256(seed.encode()), "big")
    assert 0 < scalar < P256_ORDER
    return ec.derive_private_key(scalar, ec.SECP256R1())


def point(key: ec.EllipticCurvePrivateKey) -> bytes:
    return key.public_key().public_bytes(Encoding.X962, PublicFormat.UncompressedPoint)


def expand(prk: bytes, label: str, length: int) -> bytes:
    """HKDF-Expand (RFC 5869), single block."""
    return hmac.new(prk, label.encode() + b"\x01", hashlib.sha256).digest()[:length]


def seal(key: bytes, counter: int, record_type: int, payload: bytes) -> bytes:
    """One encrypted record: 4-byte big-endian length (also the AAD), then ciphertext and tag."""
    plain = bytes([record_type]) + payload
    header = (len(plain) + 16).to_bytes(4, "big")
    nonce = bytes(4) + counter.to_bytes(8, "big")
    return header + AESGCM(key).encrypt(nonce, plain, header)


def write(name: str, title: str, values: list[tuple[str, object]]) -> None:
    lines = [f"# {title}", "# Generated by gen_fixtures.py; do not edit by hand.", ""]
    for key, value in values:
        lines.append(f"{key}={value.hex() if isinstance(value, bytes) else value}")
    (HERE / name).write_text("\n".join(lines) + "\n", encoding="ascii", newline="\n")


def protocol_v2() -> None:
    pc, phone = private_key("MobCam test PC ephemeral"), private_key("MobCam test phone ephemeral")
    shared = pc.exchange(ec.ECDH(), phone.public_key())  # X coordinate, big-endian
    assert shared == phone.exchange(ec.ECDH(), pc.public_key())
    h = sha256(b"MobCam test transcript")
    prk = hmac.new(h, shared, hashlib.sha256).digest()
    k_pc_to_phone = expand(prk, "MOBCAM v2 pc->phone", 32)
    k_phone_to_pc = expand(prk, "MOBCAM v2 phone->pc", 32)
    code = int.from_bytes(expand(prk, "MOBCAM v2 code", 4), "big") % 1_000_000

    video0 = bytes.fromhex("0000000165888400") + bytes(range(32))
    video1 = bytes.fromhex("00000001419a0200") + bytes(range(255, 223, -1))
    command0 = b"lens 2"

    write("protocol-v2.txt", "Protocol v2 key schedule and records (docs/protocol.md)", [
        ("pc_ephemeral_private", pc.private_numbers().private_value.to_bytes(32, "big")),
        ("phone_ephemeral_private", phone.private_numbers().private_value.to_bytes(32, "big")),
        ("pc_ephemeral_public", point(pc)),
        ("phone_ephemeral_public", point(phone)),
        ("shared_secret", shared),
        ("transcript_hash", h),
        ("key_pc_to_phone", k_pc_to_phone),
        ("key_phone_to_pc", k_phone_to_pc),
        ("code", f"{code:06d}"),
        # phone -> PC video records, counters 0 and 1
        ("video0_payload", video0),
        ("video0_record", seal(k_phone_to_pc, 0, 0x10, video0)),
        ("video1_payload", video1),
        ("video1_record", seal(k_phone_to_pc, 1, 0x10, video1)),
        # PC -> phone: first command, then the empty PAIRED record as the second record
        ("command0_payload", command0),
        ("command0_record", seal(k_pc_to_phone, 0, 0x11, command0)),
        ("paired1_record", seal(k_pc_to_phone, 1, 0x12, b"")),
    ])


def sei_nal(uuid: str, text: str) -> bytes:
    """Annex-B SEI NAL: user data unregistered (payload type 5), UUID, ASCII, RBSP stop bit."""
    payload = uuid.encode("ascii") + text.encode("ascii")
    assert len(payload) < 255 and b"\x00\x00" not in payload
    return bytes([0, 0, 0, 1, 0x06, 0x05, len(payload)]) + payload + b"\x80"


def sei() -> None:
    lenses = [("Ultra-wide", "0.6", "b"), ("Wide", "1", "b"), ("Telephoto", "3.4", "b"), ("Front", "1", "f")]
    values: list[tuple[str, object]] = []
    # metadata: rotation quarter turns, facing, 4-digit target height, 2-digit lens index,
    # 2-digit frame rate setting, 2-digit highest frame rate of the current lens at this size
    for i, (rotation, facing, height, lens, fps, max_fps) in enumerate(
        [(90, "b", 720, 1, 30, 60), (270, "f", 1080, 3, 60, 30)]
    ):
        text = f"{rotation // 90}{facing}{height:04d}{lens:02d}{fps:02d}{max_fps:02d}"
        values += [
            (f"metadata{i}.rotation", rotation),
            (f"metadata{i}.facing", facing),
            (f"metadata{i}.height", height),
            (f"metadata{i}.lens", lens),
            (f"metadata{i}.fps", fps),
            (f"metadata{i}.maxfps", max_fps),
            (f"metadata{i}.nal", sei_nal("MOBCAM-ROTATION!", text)),
        ]
    for i, (label, zoom, facing) in enumerate(lenses):
        values.append((f"lens{i}", f"{label}|{zoom}|{facing}"))
    text = ";".join(f"{label},{zoom},{facing}" for label, zoom, facing in lenses)
    values.append(("lenses.nal", sei_nal("MOBCAM-LENSLIST!", text)))
    write("sei.txt", "MobCam SEI NAL units: built by the phone, parsed by the PC (docs/protocol.md)", values)


if __name__ == "__main__":
    protocol_v2()
    sei()
    print("Wrote", HERE / "protocol-v2.txt", "and", HERE / "sei.txt")
